package com.tecsup.model; import jakarta.persistence.*; @Entity public class Cliente { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; public Long getId(){return id;} public void setId(Long v){id=v;}  private String nombre; public String getNombre(){return nombre;} public void setNombre(String v){this.nombre=v;} private String apellidos; public String getApellidos(){return apellidos;} public void setApellidos(String v){this.apellidos=v;} private String direccion; public String getDireccion(){return direccion;} public void setDireccion(String v){this.direccion=v;} private String estado; public String getEstado(){return estado;} public void setEstado(String v){this.estado=v;} private String nroDni; public String getNroDni(){return nroDni;} public void setNroDni(String v){this.nroDni=v;} }
